using NUnit.Framework;
using Seqeron.Mcp.Analysis.Tools;

namespace Seqeron.Mcp.Analysis.Tests;

// <auto-generated by scripts/docs/gen_emboss_wp67_tools.py: do not edit> B09 WP67 (F306): the MCP tools of the PROSITE programs; the expected text is what the installed EMBOSS 6.6.0 program writes for the example of the tool document.
[TestFixture]
public class EmbossProgramTools4Tests
{
    // the programs print the date of the run: the tools take it from the clock, so the date lines are compared as a placeholder
    private static string Norm(string s) => System.Text.RegularExpressions.Regex.Replace(System.Text.RegularExpressions.Regex.Replace(s, "# Rundate: .*", "# Rundate: X"), "(#!Date |##date )\\d{4}-\\d{2}-\\d{2}", "$1X");

    [Test]
    public void Patmatmotifs_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Patmatmotifs(">s1 test\nMAKKCAGGCLLAKKCDEFGHIKLMNPQRSTVWY\n", prositeLines: "MYPAT PS99999\n Test\n A-x(2)-C\n^A[^BJOUXZ]{2}C\n\n", documentation: new Dictionary<string, string> { ["PS99999"] = "MYPAT documentation line 1\nline 2\n" }, full: true);
        Assert.That(Norm(r.Text), Is.EqualTo("########################################\n# Program: patmatmotifs\n# Rundate: X\n# Commandline: patmatmotifs\n#    -auto\n#    -sequence sequence.dat\n#    -full\n#    -outfile out.txt\n# Report_format: dbmotif\n# Report_file: out.txt\n########################################\n\n#=======================================\n#\n# Sequence: s1     from: 1   to: 33\n# HitCount: 3\n#\n# Full: Yes\n# Prune: Yes\n# Data_file: PROSITE/prosite.lines\n#\n#=======================================\n\nLength = 4\nStart = position 12 of sequence\nEnd = position 15 of sequence\n\nMotif = MYPAT\n\nGGCLLAKKCDEFGH\n     |  |\n    12  15\n\nLength = 4\nStart = position 6 of sequence\nEnd = position 9 of sequence\n\nMotif = MYPAT\n\nMAKKCAGGCLLAKK\n     |  |\n     6  9\n\nLength = 4\nStart = position 2 of sequence\nEnd = position 5 of sequence\n\nMotif = MYPAT\n\nMAKKCAGGCL\n |  |\n 2  5\n\n\n#---------------------------------------\n#\n# Motif: MYPAT\n# Count: 3\n# \n# MYPAT documentation line 1\n# line 2\n# \n# ***************\n# \n#\n#---------------------------------------\n"));
    }

    [Test]
    public void Patmatdb_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Patmatdb(">p1 test\nMAAAAKKCAGGCLLAKKC\n", motif: "A-x(2)-C");
        Assert.That(Norm(r.Text), Is.EqualTo("########################################\n# Program: patmatdb\n# Rundate: X\n# Commandline: patmatdb\n#    -auto\n#    -sequence sequence.dat\n#    -motif A-x(2)-C\n#    -outfile out.txt\n# Report_format: dbmotif\n# Report_file: out.txt\n########################################\n\n#=======================================\n#\n# Sequence: p1     from: 1   to: 18\n# HitCount: 3\n#\n# Motif: A-X(2)-C\n#\n#=======================================\n\nLength = 4\nStart = position 15 of sequence\nEnd = position 18 of sequence\n\n\nGGCLLAKKC\n     |  |\n    15  18\n\nLength = 4\nStart = position 9 of sequence\nEnd = position 12 of sequence\n\n\nAAKKCAGGCLLAKK\n     |  |\n     9  12\n\nLength = 4\nStart = position 5 of sequence\nEnd = position 8 of sequence\n\n\nMAAAAKKCAGGCL\n    |  |\n    5  8\n\n\n#---------------------------------------\n#---------------------------------------\n\n#---------------------------------------\n# Total_sequences: 1\n# Total_length: 18\n# Reported_sequences: 1\n# Reported_hitcount: 3\n#---------------------------------------\n"));
    }

    [Test]
    public void Prosextract_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Prosextract("ID   A_PAT; PATTERN.\nAC   PS99999;\nDT   01-APR-1990 CREATED.\nDE   Test pattern site.\nPA   A-x(2)-C.\n//\n", prositeDoc: "{PDOC99999}\n{PS99999; A_PAT}\n{BEGIN}\nDocumentation of A_PAT.\n{END}\n");
        Assert.That(Norm(r.Text), Is.EqualTo("A_PAT PS99999\n Test\n A-x(2)-C\n^A[^BJOUXZ]{2}C\n\n"));
        Assert.That(Norm(r.Files["/usr/share/EMBOSS/data/PROSITE/PS99999"]), Is.EqualTo("Documentation of A_PAT.\n"));
    }

    [Test]
    public void Tools_RefuseAnEmptyInputAndABadPatternWithTheMessagesOfTheLibrary()
    {
        Assert.Throws<ArgumentException>(() => AnalysisTools.Patmatmotifs("", prositeLines: "x"));
        Assert.Throws<ArgumentException>(() => AnalysisTools.Patmatdb(">p\nMAAAK\n", ""));
        Assert.Throws<ArgumentException>(() => AnalysisTools.Prosextract("", ""));
        var e = Assert.Throws<ArgumentException>(() => AnalysisTools.Patmatdb(">p\nMAAAK\n", "A-x(2"));
        Assert.That(e!.Message, Does.Contain("Unmatched '(' in A-X(2"));
        var f = Assert.Throws<ArgumentException>(() => AnalysisTools.Patmatdb(">p\nMAAAK\n", "A(2,1)"));
        Assert.That(f!.Message, Does.Contain("numbers out of order in {} quantifier"));
        var g = Assert.Throws<ArgumentException>(() => AnalysisTools.Patmatmotifs(">p\nMAAAK\n"));
        Assert.That(g!.Message, Does.Contain("PROSEXTRACT needs running"));
    }
}
